class.description:
A [PerformanceRecordingProfile] selects the columns of a recording (builtins, [Performance] monitors, custom monitors, native metric sources and pushed metrics), the sampling intervals, the size of the ring buffer and the CSV output. Save it as a [code].tres[/code] file to use it from the project settings ([member ProjectSettings.debug/performance_recording/profile]) or the command line ([code]--record-performance-profile[/code]).
A new profile starts with a default selection: the builtins [constant PerformanceRecorder.BUILTIN_FRAME], [constant PerformanceRecorder.BUILTIN_TIME_USEC], [constant PerformanceRecorder.BUILTIN_FRAME_TIME], [constant PerformanceRecorder.BUILTIN_PROCESS_TIME], [constant PerformanceRecorder.BUILTIN_PHYSICS_TIME], [constant PerformanceRecorder.BUILTIN_PHYSICS_STEPS], [constant PerformanceRecorder.BUILTIN_PROCESS_MEMORY] and [constant PerformanceRecorder.BUILTIN_RECORDER_TIME], and the monitors [constant Performance.TIME_FPS], [constant Performance.MEMORY_STATIC], [constant Performance.OBJECT_COUNT], [constant Performance.OBJECT_NODE_COUNT], [constant Performance.RENDER_TOTAL_OBJECTS_IN_FRAME], [constant Performance.RENDER_TOTAL_PRIMITIVES_IN_FRAME], [constant Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME] and [constant Performance.RENDER_VIDEO_MEM_USED].
[codeblocks]
[gdscript]
var profile = PerformanceRecordingProfile.new()
profile.builtins = [PerformanceRecorder.BUILTIN_FRAME_TIME, PerformanceRecorder.BUILTIN_GPU_TIME]
profile.monitors = [Performance.TIME_FPS, Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME]
profile.metrics = ["enemies_alive"]
profile.output_path = "user://perf/{platform}_{date}_{time}.csv"
PerformanceRecorder.start(profile)
[/gdscript]
[csharp]
var profile = new PerformanceRecordingProfile();
profile.Builtins = [(int)PerformanceRecorder.Builtin.FrameTime, (int)PerformanceRecorder.Builtin.GpuTime];
profile.Monitors = [(int)Performance.Monitor.TimeFps, (int)Performance.Monitor.RenderTotalDrawCallsInFrame];
profile.Metrics = ["enemies_alive"];
profile.OutputPath = "user://perf/{platform}_{date}_{time}.csv";
PerformanceRecorder.Start(profile);
[/csharp]
[/codeblocks]
